#[test]
fn supports_null_preprocessing_directives() {
    let program = r#"#
%:
# /**/
%: // comment
#\
 /* physically spliced */
#if 1
#
#else
#error selected the wrong branch
#endif
#if 0
# inactive tokens are ignored
%:
#error inactive error
#endif
int main(void) { return 0; }
"#;

    assert_eq!(interpret(program).unwrap(), 0);
}

