    assert_eq!(interpret(lf).unwrap(), 3);

    let crlf = "#define VALUE 2 \\\r\n    + 3\r\n#if VALUE == \\\r\n    5\r\nint main(void) { return VALUE; }\r\n#else\r\nint main(void) { return 0; }\r\n#endif\r\n";
