#[test]
fn character_pointer_output_parameters_write_null_and_interior_pointers() {
    let program = r#"
void set_end(char **out, char *value) {
    if (out) {
        *out = value;
    }
}

void forward_end(char **out, char *value) {
    set_end(out, value);
}

int main(void) {
    char text[] = "123abc";
    char *end = 0;

    set_end(0, text);
    if (end != 0) {
        return 1;
    }
    set_end(&end, text + 3);
    if (*end != 'a') {
        return 2;
    }
    set_end(&end, 0);
    if (end != 0) {
        return 3;
    }
    forward_end(&end, text + 1);
    return end[0] == '2' ? 0 : 4;
}
"#;

    assert_eq!(interpret(program).unwrap(), 0);
}

