#[test]
fn supports_deterministic_random_standard_library_functions() {
    let program = r#"
int rand(void);
void srand(unsigned int seed);

int main(void) {
    int default_first = rand();
    int default_second = rand();

    srand(1);
    if (rand() != default_first || rand() != default_second) {
        return 1;
    }

    srand(123);
    int seeded_first = rand();
    int seeded_second = rand();
    srand(123);
    if (rand() != seeded_first || rand() != seeded_second) {
        return 2;
    }

    srand(124);
    if (rand() == seeded_first) {
        return 3;
    }

    srand(99);
    for (int i = 0; i < 64; i++) {
        int value = rand();
        if (value < 0 || value > 32767) {
            return 4;
        }
    }
    return 0;
}
"#;

    assert_eq!(interpret(program).unwrap(), 0);
    assert_eq!(interpret(program).unwrap(), 0);
}

#[test]
fn exit_unwinds_nested_calls_to_an_interpreter_owned_result() {
    let program = r#"
void exit(int status);
int marker = 0;

void inner(int status) {
    marker = 1;
    exit(status);
    marker = 2;
}

int outer(void) {
    inner(37);
    marker = 3;
    return 99;
}

int main(void) {
    int result = outer();
    marker = 4;
    return result;
}
"#;

    assert_eq!(interpret(program).unwrap(), 37);
    assert_eq!(interpret("int main(void) { return 5; }\n").unwrap(), 5);
}

